select *
from customer;

#Q1. What is the total revenue generated by male vs. female customers?
select gender, sum(purchase_amount)
from customer
group by 1;

#Q2. Which customers used a discount but still spent more than the average purchase amount? 
select distinct customer_id
from customer
where purchase_amount>( select avg(purchase_amount) from customer) and discount_applied='yes'
;

#Q3. Which are the top 5 products with the highest average review rating?
select item_purchased,round(avg(review_rating),2)
from customer
group by 1
order by 1 desc
limit 5;

#Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select shipping_type,avg(purchase_amount)
from customer
where shipping_type ='Standard' or shipping_type ='Express'
group by 1;

#Q5. Do subscribed customers spend more? Compare average spend and total revenue 
select subscription_status,count(customer_id) as total_customers,(avg(purchase_amount)) as Avg_spent,sum(purchase_amount) as total_revnue
from customer
group by 1;
# no. avg and total revenue are less by subscribed customers than regulars

#Q6. Which 5 products have the highest percentage of purchases with discounts applied?
# what percentage of each product has discounts applied?
# i want product , % of discount applied for 


SELECT item_purchased,
       ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;


#Q7. Segment customers into New, Returning, and Loyal based on their total 
#number of previous purchases, and show the count of each segment. 

with cte1 as 
(
select customer_id,previous_purchases,
case
	when previous_purchases<10 then "new"
    when previous_purchases>=10 and previous_purchases<50 then "Returning"
    else "Loyal"
end as Cust_type
from customer
)

select Cust_type, count(Cust_type)
from cte1
group by 1;

# Q8. What are the top 3 most purchased products within each category?
# category, 3,itempurchased

with cte2 as
(
select category,item_purchased,count(purchase_amount) as total_amount,
dense_rank()over(partition by category order by count(purchase_amount) desc ) as rnk
from customer
group by category,item_purchased
)
select *
from cte2
where rnk in ('1','2','3')
;


#Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

select subscription_status,count(customer_id) As repeat_customers
from customer
where previous_purchases>5
group by 1
;

#Q10. What is the revenue contribution of each age group? 

select age_group, sum(purchase_amount)
from customer
group by 1
order by sum(purchase_amount) desc;



